#!/usr/bin/env python3
"""fleetrun.py -- SSH-less remote-exec simulator for fleet automation practice.

Hosts are simulated as local directories under fleet/<hostname>/, each holding
a facts.json file (os, cpu_count, tags, ...). A tiny predicate language selects
hosts:

    expr    := and_expr (OR and_expr)*
    and_expr:= cmp_expr (AND cmp_expr)*
    cmp_expr:= operand (EQ | CONTAINS) operand?
    operand := IDENT | STRING | NUMBER | '(' expr ')'

Operators: ==, contains; boolean combinators: and, or; parentheses group.
Identifiers are field access into {"hostname": ..., **facts}; dots allow
nested access (a.b.c). `contains`: membership for lists, substring for strings.

Example:
    python3 fleetrun.py --select 'tags contains web and os == debian' \
        -- sh -c 'echo {hostname} runs {fact:os}'
"""

from __future__ import annotations

import argparse
import json
import re
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

DEFAULT_FLEET_DIR = Path(__file__).resolve().parent / "fleet"

# --------------------------------------------------------------------------
# Predicate language: tokenizer
# --------------------------------------------------------------------------

_TOKEN_SPEC = [
    ("WS", r"\s+"),
    ("LPAREN", r"\("),
    ("RPAREN", r"\)"),
    ("EQ", r"=="),
    ("STRING", r'"[^"]*"|\'[^\']*\''),
    ("NUMBER", r"\d+(?:\.\d+)?"),
    ("IDENT", r"[A-Za-z_][A-Za-z0-9_]*"),
]
_MASTER_RE = re.compile("|".join(f"(?P<{name}>{pat})" for name, pat in _TOKEN_SPEC))

KEYWORDS = {"and": "AND", "or": "OR", "contains": "CONTAINS"}


class ParseError(ValueError):
    pass


def tokenize(text: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    pos = 0
    while pos < len(text):
        m = _MASTER_RE.match(text, pos)
        if not m:
            raise ParseError(f"unexpected character {text[pos]!r} at index {pos}")
        kind = m.lastgroup
        value = m.group()
        pos = m.end()
        if kind == "WS":
            continue
        if kind == "IDENT" and value in KEYWORDS:
            kind = KEYWORDS[value]
        elif kind == "STRING":
            value = value[1:-1]
        tokens.append((kind, value))
    return tokens


# --------------------------------------------------------------------------
# Predicate language: recursive-descent parser
#
# AST nodes are tuples:
#   ("or", lhs, rhs) ("and", lhs, rhs) ("eq", lhs, rhs)
#   ("contains", lhs, rhs) ("field", dotted.name) ("lit", value)
#
# Precedence (loosest to tightest): or < and < comparison; parentheses bind.
# --------------------------------------------------------------------------

class Parser:
    def __init__(self, tokens: list[tuple[str, str]]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> tuple[str, str] | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def take(self, kind: str) -> tuple[str, str]:
        tok = self.peek()
        if tok is None or tok[0] != kind:
            raise ParseError(
                f"expected {kind}, got {tok[1]!r if tok else 'end of input'}"
            )
        self.pos += 1
        return tok

    def parse(self):
        node = self.parse_or()
        if self.peek() is not None:
            raise ParseError(f"trailing input starting at {self.peek()[1]!r}")
        return node

    def parse_or(self):
        node = self.parse_and()
        while self.peek() and self.peek()[0] == "OR":
            self.take("OR")
            node = ("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_cmp()
        while self.peek() and self.peek()[0] == "AND":
            self.take("AND")
            node = ("and", node, self.parse_cmp())
        return node

    def parse_cmp(self):
        lhs = self.parse_atom()
        tok = self.peek()
        if tok and tok[0] in ("EQ", "CONTAINS"):
            self.pos += 1
            op = "eq" if tok[0] == "EQ" else "contains"
            return (op, lhs, self.parse_atom())
        return lhs

    def parse_atom(self):
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of expression")
        if tok[0] == "LPAREN":
            self.take("LPAREN")
            node = self.parse_or()
            self.take("RPAREN")
            return node
        if tok[0] == "STRING":
            self.pos += 1
            return ("lit", tok[1])
        if tok[0] == "NUMBER":
            self.pos += 1
            value: object = float(tok[1])
            if value.is_integer():
                value = int(value)
            return ("lit", value)
        if tok[0] == "IDENT":
            self.pos += 1
            return ("field", tok[1])
        raise ParseError(f"unexpected token {tok[1]!r}")


def parse_predicate(text: str):
    """Parse a predicate expression into an AST. Raises ParseError."""
    return Parser(tokenize(text)).parse()


# --------------------------------------------------------------------------
# Evaluation
# --------------------------------------------------------------------------

def resolve_field(name: str, ctx: dict):
    node: object = ctx
    for part in name.split("."):
        if isinstance(node, dict) and part in node:
            node = node[part]
        else:
            return None
    return node


def eval_predicate(node, ctx: dict) -> bool:
    op = node[0]
    if op == "or":
        return eval_predicate(node[1], ctx) or eval_predicate(node[2], ctx)
    if op == "and":
        return eval_predicate(node[1], ctx) and eval_predicate(node[2], ctx)
    if op == "eq":
        return _loose_eq(resolve_operand(node[1], ctx), resolve_operand(node[2], ctx))
    if op == "contains":
        haystack = resolve_operand(node[1], ctx)
        needle = resolve_operand(node[2], ctx)
        if isinstance(haystack, (list, tuple)):
            return any(_loose_eq(item, needle) for item in haystack)
        if isinstance(haystack, str):
            return str(needle) in haystack
        return False
    raise ParseError(f"cannot evaluate node {node!r}")


def resolve_operand(node, ctx: dict):
    if node[0] == "field":
        return resolve_field(node[1], ctx)
    return node[1]


def _loose_eq(a, b) -> bool:
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, (int, float)) or isinstance(b, (int, float)):
        try:
            return float(a) == float(b)  # type: ignore[arg-type]
        except (TypeError, ValueError):
            return False
    return a == b


# --------------------------------------------------------------------------
# Fleet simulation
# --------------------------------------------------------------------------

@dataclass
class Host:
    hostname: str
    facts: dict
    directory: Path

    @property
    def ctx(self) -> dict:
        return {"hostname": self.hostname, **self.facts}


def load_hosts(fleet_dir: Path) -> list[Host]:
    hosts = []
    for entry in sorted(fleet_dir.iterdir()):
        facts_file = entry / "facts.json"
        if entry.is_dir() and facts_file.is_file():
            hosts.append(Host(entry.name, json.loads(facts_file.read_text()), entry))
    return hosts


_HOSTNAME_RE = re.compile(r"\{hostname\}")
_FACT_RE = re.compile(r"\{fact:([A-Za-z_][A-Za-z0-9_.]*)\}")


def render_template(template: str, host: Host) -> str:
    def fact_sub(m: re.Match) -> str:
        value = resolve_field(m.group(1), host.ctx)
        if value is None:
            raise KeyError(m.group(0))
        return str(value)

    out = _HOSTNAME_RE.sub(host.hostname, template)
    return _FACT_RE.sub(fact_sub, out)


def execute_on_host(host: Host, template: str) -> dict:
    cmd = render_template(template, host)
    proc = subprocess.run(cmd, shell=True, cwd=host.directory,
                          capture_output=True, text=True)
    return {
        "hostname": host.hostname,
        "command": cmd,
        "exit_code": proc.returncode,
        "stdout": proc.stdout.strip(),
        "stderr": proc.stderr.strip(),
    }


def run_fleet(command_template: str, select_expr: str | None,
              fleet_dir: Path = DEFAULT_FLEET_DIR) -> dict:
    ast = parse_predicate(select_expr) if select_expr is not None else None
    selected = [h for h in load_hosts(fleet_dir)
                if ast is None or eval_predicate(ast, h.ctx)]
    results = [execute_on_host(h, command_template) for h in selected]
    failures = [{"hostname": r["hostname"], "exit_code": r["exit_code"]}
                for r in results if r["exit_code"] != 0]
    return {
        "selected": [h.hostname for h in selected],
        "ok": sum(1 for r in results if r["exit_code"] == 0),
        "failed": len(failures),
        "failures": failures,
        "results": results,
    }


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------

def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="SSH-less remote-exec simulator")
    ap.add_argument("--fleet", type=Path, default=DEFAULT_FLEET_DIR,
                    help="directory containing <hostname>/facts.json hosts")
    ap.add_argument("--select", default=None,
                    help="predicate expression, e.g. \"tags contains web\"")
    ap.add_argument("command", nargs=argparse.REMAINDER,
                    help="command template (use -- to separate); supports "
                         "{hostname} and {fact:KEY}")
    args = ap.parse_args(argv)

    if not args.command:
        ap.error("no command given (use -- to separate it from options)")
    template = " ".join(args.command)

    try:
        summary = run_fleet(template, args.select, args.fleet)
    except (ParseError, KeyError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except FileNotFoundError:
        print(f"error: fleet directory not found: {args.fleet}", file=sys.stderr)
        return 2

    print(json.dumps(summary, indent=2))
    return 1 if summary["failed"] else 0


if __name__ == "__main__":
    sys.exit(main())

